referenceFix.find:
  setLoading(true)
  api
    .search(debouncedTerm)
    .then((result) => {
      setResponse(result)
      setActiveIndex(0)
    })
    .catch(() => setResponse({ query: debouncedTerm, results: [] }))
    .finally(() => setLoading(false))
}, [debouncedTerm])

referenceFix.replace:
  const controller = new AbortController()
  setLoading(true)
  api
    .search(debouncedTerm, controller.signal)
    .then((result) => {
      setResponse(result)
      setActiveIndex(0)
    })
    .catch(() => {
      if (!controller.signal.aborted) setResponse({ query: debouncedTerm, results: [] })
    })
    .finally(() => {
      if (!controller.signal.aborted) setLoading(false)
    })
  return () => controller.abort()
}, [debouncedTerm])
